// Custom Worker entry: login gate + OpenNext's fetch handler + the daily cron (see wrangler.jsonc "triggers").
// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- ts-expect-error would fail once .open-next exists
// @ts-ignore generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
import { type Env, runDaily, SESSION_COOKIE, sessionUser } from "./lib/hub";

// /api/report and /api/backup authenticate with per-site HMAC instead; /api/pair proves the site by calling it back. Static files never reach the worker (assets binding).
const PUBLIC = new Set(["/login", "/api/report", "/api/backup", "/api/pair", "/favicon.ico"]);

export default {
  // Gate here, not in Next proxy: Node proxy is experimental on OpenNext Cloudflare.
  // Covers pages AND server actions (they POST to page URLs).
  async fetch(req: Request, env: Env, ctx: ExecutionContext) {
    const url = new URL(req.url);
    const token = req.headers.get("cookie")?.match(new RegExp(`(?:^|;\\s*)${SESSION_COOKIE}=([^;]+)`))?.[1];
    if (!PUBLIC.has(url.pathname) && !(await sessionUser(env, token))) {
      return req.method === "GET" ? Response.redirect(new URL("/login", url), 302) : new Response("Unauthorized", { status: 401 });
    }
    return handler.fetch(req, env, ctx);
  },
  async scheduled(_controller: ScheduledController, env: Env, ctx: ExecutionContext) {
    ctx.waitUntil(runDaily(env));
  },
};
